import { useEffect, useRef, type KeyboardEvent } from 'react';

export interface IChatInputProps {
  value: string;
  onChange: (value: string) => void;
  onKeyDown?: (event: KeyboardEvent<HTMLTextAreaElement>) => void;
  placeholder?: string;
  disabled?: boolean;
  /** Height (px) the field grows to before it scrolls internally. */
  maxHeight?: number;
  ariaLabel?: string;
  className?: string;
}

/**
 * Auto-growing chat input, deliberately NOT `erxes-ui`'s `Textarea`.
 *
 * The shared textarea ships a focus shadow and a fixed height, which in a chat
 * composer produced a bright focus ring inside the composer card plus native
 * scrollbar arrows on a one-line field. This one is chrome-free: it owns no
 * border, no ring and no background (the composer card draws those), and it is
 * exactly as tall as its content — the scrollbar only appears once the text
 * passes `maxHeight`.
 */
export const ChatInput = ({
  value,
  onChange,
  onKeyDown,
  placeholder,
  disabled = false,
  maxHeight = 168,
  ariaLabel,
  className,
}: IChatInputProps) => {
  const inputRef = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    const node = inputRef.current;

    if (!node) {
      return;
    }

    // Measure from scratch: shrinking needs the height reset first, otherwise
    // `scrollHeight` keeps reporting the previous (taller) box.
    node.style.height = 'auto';
    node.style.height = `${Math.min(node.scrollHeight, maxHeight)}px`;
    node.style.overflowY = node.scrollHeight > maxHeight ? 'auto' : 'hidden';
  }, [value, maxHeight]);

  return (
    <textarea
      ref={inputRef}
      value={value}
      onChange={(event) => onChange(event.target.value)}
      onKeyDown={onKeyDown}
      placeholder={placeholder}
      disabled={disabled}
      rows={1}
      aria-label={ariaLabel}
      className={`ea:w-full ea:resize-none ea:border-0 ea:bg-transparent ea:text-sm ea:leading-5 ea:text-foreground ea:shadow-none ea:outline-none ea:ring-0 ea:placeholder:text-muted-foreground/70 ea:focus:outline-none ea:focus-visible:outline-none ea:disabled:cursor-not-allowed ea:disabled:opacity-60 ea:md:text-sm ${
        className ?? ''
      }`}
    />
  );
};
